using DangPhatFlex.Web.Models;
using DangPhatFlex.Web.Services;

namespace DangPhatFlex.Web.Data;

// Second backlog batch of 12 SEO articles (2/day, 8:00 & 17:00, 01/08-06/08/2026), continuing
// from NewsBacklogSeeder (20/07-31/07). Same content markup convention and keyword-targeting
// approach; new angles chosen to avoid overlapping the previous 27 articles. Idempotent via a
// marker-slug check.
public static class NewsBacklogSeeder2
{
    public static void Seed(AppDbContext context, ISlugService slugService)
    {
        var markerSlug = slugService.GenerateSlug("Bảo trì định kỳ hệ thống sprinkler có ống mềm nối đầu phun: Tần suất và hạng mục kiểm tra");
        if (context.NewsArticles.Any(a => a.Slug == markerSlug))
            return;

        var articles = BuildArticles();

        foreach (var article in articles)
            article.Slug = slugService.GenerateSlug(article.Title);

        context.NewsArticles.AddRange(articles);
        context.SaveChanges();
    }

    private static NewsArticle[] BuildArticles() => new[]
    {
        new NewsArticle
        {
            Title = "Bảo trì định kỳ hệ thống sprinkler có ống mềm nối đầu phun: Tần suất và hạng mục kiểm tra",
            Summary = "Lịch bảo trì định kỳ cho hệ thống sprinkler dùng ống mềm nối đầu phun: kiểm tra hàng tháng, kiểm tra toàn diện hàng năm và các hạng mục cần ghi nhận mỗi lần.",
            Content = "Một hệ thống chữa cháy sprinkler chỉ vận hành đáng tin cậy khi được bảo trì định kỳ, chứ không phải chỉ kiểm tra một lần lúc nghiệm thu rồi bỏ ngỏ trong suốt vòng đời công trình. Ống mềm nối đầu phun sprinkler là một trong những điểm nối dễ bị ảnh hưởng bởi rung động, va chạm trần, hoặc ẩm mốc theo thời gian, nên cần có mặt trong lịch kiểm tra định kỳ của bộ phận vận hành tòa nhà, không riêng gì bơm và tủ điều khiển.\n\n## Kiểm tra trực quan hàng tháng\n\nỞ chu kỳ ngắn, việc kiểm tra chủ yếu là quan sát bằng mắt, không cần tháo lắp. Nhân viên vận hành nên dành thời gian đi qua các khu vực có trần thả để nhìn tổng thể hệ thống ống mềm nối đầu phun, tập trung vào:\n\n- Dấu hiệu rò rỉ nước hoặc vệt ẩm quanh đầu ren kết nối\n- Ống mềm bị võng, cong gập bất thường ngoài bán kính uốn cho phép\n- Đầu phun bị che khuất bởi vật dụng, trần trang trí lắp thêm sau này\n- Dấu hiệu ăn mòn, ố vàng bất thường trên thân ống dạng gân xoắn\n\nNếu phát hiện bất thường, cần ghi nhận vị trí cụ thể để đội kỹ thuật xử lý ở lần bảo trì gần nhất, tránh để tồn đọng qua nhiều chu kỳ.\n\n## Kiểm tra toàn diện định kỳ hàng năm\n\nBên cạnh kiểm tra trực quan hàng tháng, nên có một đợt kiểm tra sâu hơn mỗi năm, thường gắn với đợt bảo trì tổng thể hệ thống PCCC của tòa nhà. Ở lần này, đội kỹ thuật cần:\n\n- Kiểm tra lực siết tại các đầu ren kết nối vào đường ống chính và đầu phun\n- Đối chiếu vị trí lắp đặt thực tế với bản vẽ shopdrawing, phát hiện sai lệch nếu có\n- Xác nhận toàn bộ ống mềm nối đầu phun trong khu vực vẫn thuộc đúng chủng loại và thông số theo thiết kế ban đầu\n- Thử áp lực cục bộ tại một số điểm đại diện nếu quy trình vận hành tòa nhà yêu cầu\n\nDoanh nghiệp có thể tham khảo thêm về thông số kỹ thuật và tiêu chuẩn sản xuất của dây mềm nối đầu phun sprinkler tại bài viết về [tiêu chuẩn UL/FM/TCVN và hướng dẫn lắp đặt](/tin-tuc/ong-mem-noi-dau-phun-sprinkler-tieu-chuan-ulfmtcvn-va-huong-dan-lap-dat) để đối chiếu khi kiểm tra.\n\n## Hạng mục cần ghi nhận sau mỗi lần kiểm tra\n\nDù kiểm tra hàng tháng hay hàng năm, việc lập biên bản là bước không nên bỏ qua. Một biên bản bảo trì tốt nên có:\n\n1. Ngày kiểm tra và người thực hiện\n2. Vị trí, khu vực, số lượng ống mềm nối đầu phun được kiểm tra\n3. Tình trạng phát hiện (bình thường / cần theo dõi / cần thay thế)\n4. Hành động đã thực hiện hoặc đề xuất cho lần bảo trì tiếp theo\n\nViệc lưu trữ dữ liệu qua nhiều năm giúp ban quản lý tòa nhà nhận ra xu hướng xuống cấp sớm, thay vì chỉ phản ứng khi sự cố đã xảy ra.\n\n## Vì sao nên đưa ống mềm vào lịch bảo trì riêng\n\nNhiều đơn vị vận hành chỉ tập trung bảo trì bơm chữa cháy và tủ báo cháy mà bỏ quên các điểm nối nhỏ như ống mềm nối đầu phun. Trong khi đó, đây lại là bộ phận nằm gần vị trí sử dụng cuối cùng của hệ thống, ảnh hưởng trực tiếp đến khả năng nước đến được đầu phun khi có cháy. Nếu cần tư vấn thêm về chủng loại phù hợp để thay thế trong quá trình bảo trì, có thể tham khảo [danh mục sản phẩm](/san-pham) hoặc [liên hệ đội ngũ kỹ thuật](/lien-he) của Đăng Phát Flex.",
            CoverImageUrl = "/images/products/accessory-square-bar.jpg",
            CoverImageAlt = "Thanh ngang vuông phụ kiện lắp đặt ống mềm nối đầu phun dùng trong bảo trì hệ thống sprinkler",
            PublishedAt = new DateTime(2026, 8, 1, 8, 0, 0, DateTimeKind.Utc),
            MetaTitle = "Lịch Bảo Trì Định Kỳ Ống Mềm Nối Đầu Phun | Đăng Phát Flex",
            MetaDescription = "Hướng dẫn tần suất và hạng mục bảo trì định kỳ hệ thống sprinkler có ống mềm nối đầu phun: kiểm tra hàng tháng, kiểm tra toàn diện hàng năm và cách ghi nhận biên bản."
